import { defineConfig } from "vite";
import react from "@vitejs/plugin-react-swc";
import path from "path";
import { componentTagger } from "lovable-tagger";

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => ({
  server: {
    host: "::",
    port: 8080,
    hmr: {
      overlay: false,
    },
  },
  plugins: [react(), mode === "development" && componentTagger()].filter(Boolean),
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
  build: {},
}));

import { lazy, Suspense, useEffect } from "react";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { AuthProvider, useAuth } from "@/hooks/useAuth";
import { useFeatureFlag } from "@/hooks/useFeatureFlags";
import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
import { ThemeProvider } from "@/components/ThemeProvider";
import MaintenancePage from "@/components/MaintenancePage";
import SeoHead from "@/components/SeoHead";
import ChatWidget from "@/components/ChatWidget";
import { supabase } from "@/integrations/supabase/client";

// Eager imports — core pages users navigate between constantly (no Suspense flash)
import Index from "./pages/Index";
import Auth from "./pages/Auth";
import Settings from "./pages/Settings";
import Profile from "./pages/Profile";
import Billing from "./pages/Billing";
import Team from "./pages/Team";
import Tasks from "./pages/Tasks";
import Activity from "./pages/Activity";

// Sidebar-accessible pages — eager to avoid flash on click
import Changelog from "./pages/Changelog";
import RequestFeature from "./pages/RequestFeature";
import CareerSettings from "./pages/CareerSettings";
import Integrations from "./pages/Integrations";
import Reports from "./pages/Reports";
import AgencyHub from "./pages/AgencyHub";
import TalentPool from "./pages/TalentPool";
import Sequences from "./pages/Sequences";

// Lazy imports — infrequent or large pages
const Admin = lazy(() => import("./pages/Admin"));
const NotFound = lazy(() => import("./pages/NotFound"));
const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
const BookDemo = lazy(() => import("./pages/BookDemo"));
const Apply = lazy(() => import("./pages/Apply"));
const CareerPage = lazy(() => import("./pages/CareerPage"));
const CareerJobDetail = lazy(() => import("./pages/CareerJobDetail"));
const LandingPage = lazy(() => import("@/components/LandingPage"));
const SharedPortal = lazy(() => import("./pages/SharedPortal"));
const BookInterview = lazy(() => import("./pages/BookInterview"));

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000,
      gcTime: 10 * 60 * 1000,
      refetchOnWindowFocus: false,
      refetchOnMount: false,
      retry: 1,
    },
  },
});

/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
const PageLoader = () => (
  <div className="flex h-svh w-full overflow-hidden">
    {/* Sidebar skeleton — matches sidebar width */}
    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
      <div className="px-4 py-4">
        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
      </div>
      <div className="border-t border-border" />
      <div className="p-3 space-y-2">
        {[1, 2, 3, 4].map((i) => (
          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
        ))}
      </div>
    </div>
    {/* Content area skeleton */}
    <div className="flex-1 flex flex-col min-w-0">
      {/* Header skeleton */}
      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
        <div className="flex items-center gap-3">
          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
        </div>
      </div>
      {/* Body skeleton */}
      <div className="flex-1 overflow-y-auto p-6">
        <div className="max-w-5xl mx-auto space-y-4">
          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
            ))}
          </div>
        </div>
      </div>
    </div>
  </div>
);

const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
  const { isAdmin, loading } = useAuth();

  // Don't block rendering while loading — only gate when we know maintenance is on
  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
  return <>{children}</>;
};

const RootRoute = () => {
  const { user, loading } = useAuth();
  if (loading) return <PageLoader />;
  return user ? <Index /> : <LandingPage />;
};

/** Silently prefetches sidebar-linked pages so they open instantly on first click */
const DataPrefetcher = () => {
  const { user } = useAuth();
  const qc = useQueryClient();

  useEffect(() => {
    // Prefetch public data that doesn't require auth
    qc.prefetchQuery({
      queryKey: ["changelog_public"],
      queryFn: async () => {
        const { data } = await (supabase as any)
          .from("changelog")
          .select("id, version, title, description, category, published_at")
          .eq("status", "published")
          .order("published_at", { ascending: false });
        return data ?? [];
      },
      staleTime: 5 * 60 * 1000,
    });
    qc.prefetchQuery({
      queryKey: ["feature_requests"],
      queryFn: async () => {
        const { data } = await (supabase as any)
          .from("feature_requests")
          .select("*")
          .order("created_at", { ascending: false });
        return data ?? [];
      },
      staleTime: 5 * 60 * 1000,
    });
  }, []);

  useEffect(() => {
    if (!user) return;
    qc.prefetchQuery({
      queryKey: ["my_feature_votes"],
      queryFn: async () => {
        const { data } = await (supabase as any)
          .from("feature_request_votes")
          .select("feature_request_id")
          .eq("user_id", user.id);
        return (data ?? []).map((v: any) => v.feature_request_id);
      },
      staleTime: 5 * 60 * 1000,
    });
  }, [user?.id]);

  return null;
};

const App = () => (
  <QueryClientProvider client={queryClient}>
    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
      <AuthProvider>
        <DataPrefetcher />
        <TooltipProvider>
          <Sonner />
          <BrowserRouter>
            <SeoHead />
            <Suspense fallback={<PageLoader />}>
              <Routes>
                {/* Public pages — outside MaintenanceGate so candidates/guests can always access */}
                <Route path="/apply/:jobId" element={<Apply />} />
                <Route path="/careers/:slug" element={<CareerPage />} />
                <Route path="/careers/:slug/jobs/:jobId" element={<CareerJobDetail />} />
                <Route path="/shared/:token" element={<SharedPortal />} />
                <Route path="/book/:token" element={<BookInterview />} />
                <Route path="*" element={
                  <MaintenanceGate>
                    <Routes>
                      <Route path="/auth" element={<Auth />} />
                      <Route path="/" element={<RootRoute />} />
                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
                      <Route path="/activity" element={<ProtectedRoute><Activity /></ProtectedRoute>} />
                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
                      <Route path="/integrations" element={<ProtectedRoute><Integrations /></ProtectedRoute>} />
                      <Route path="/reports" element={<ProtectedRoute><Reports /></ProtectedRoute>} />
                      <Route path="/agency" element={<ProtectedRoute><AgencyHub /></ProtectedRoute>} />
                      <Route path="/talent-pool" element={<ProtectedRoute><TalentPool /></ProtectedRoute>} />
                      <Route path="/sequences" element={<ProtectedRoute><Sequences /></ProtectedRoute>} />
                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
                      <Route path="/book-demo" element={<BookDemo />} />
                      <Route path="/request-feature" element={<RequestFeature />} />
                      <Route path="/changelog" element={<Changelog />} />
                      <Route path="/payment/callback" element={<PaymentCallback />} />
                      <Route path="*" element={<NotFound />} />
                    </Routes>
                  </MaintenanceGate>
                } />
              </Routes>
            </Suspense>
            <ChatWidget />
          </BrowserRouter>
        </TooltipProvider>
      </AuthProvider>
    </ThemeProvider>
  </QueryClientProvider>
);

export default App;

